const clients = new Map(); // client_id -> Map(key -> value)

function requireNonEmptyString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`${name} must be a non-empty string`);
  }
}

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open (or reset) an isolated key/value map for a client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Unique non-empty client identifier.' }
        },
        required: ['client_id']
      }
    },
    {
      name: 'client_put',
      description: 'Store a key/value pair in the calling client isolated map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value']
      }
    },
    {
      name: 'client_get',
      description: 'Retrieve a value by key from the calling client isolated map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key']
      }
    }
  ];
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      requireNonEmptyString(args.client_id, 'client_id');
      clients.set(args.client_id, new Map());
      return textResult(args.client_id);
    }
    case 'client_put': {
      requireNonEmptyString(args.client_id, 'client_id');
      requireNonEmptyString(args.key, 'key');
      requireNonEmptyString(args.value, 'value');
      const store = clients.get(args.client_id);
      if (!store) throw new Error(`unknown client: ${args.client_id}`);
      store.set(args.key, args.value);
      return textResult('ok');
    }
    case 'client_get': {
      requireNonEmptyString(args.client_id, 'client_id');
      requireNonEmptyString(args.key, 'key');
      const store = clients.get(args.client_id);
      if (!store) throw new Error(`unknown client: ${args.client_id}`);
      if (!store.has(args.key)) throw new Error(`unknown key: ${args.key}`);
      return textResult(store.get(args.key));
    }
    default:
      throw new Error(`unknown tool: ${name}`);
  }
}
```

